//! Turning a declaration into each side's constants.
//!
//! The two emitters are deliberately dumb: they know the shape of the text and
//! nothing about what an opcode means. Sizes are **derived** here and written
//! nowhere, which is the point of the whole tool — the size of an instruction
//! used to be written down three times, and one copy went stale.

use crate::declaration::{Declaration, Opcode};

/// The five header lines every generated file carries, with the comment marker
/// each language wants in front.
fn header(name: &str, source: &str, comment: &str) -> Vec<String> {
    // An empty line takes the marker and nothing else: a trailing space is
    // invisible in review and shows up as a diff forever after.
    let at = |s: &str| match (comment.is_empty(), s.is_empty()) {
        (true, _) => s.to_string(),
        (false, true) => comment.to_string(),
        (false, false) => format!("{comment} {s}"),
    };
    vec![
        at(&format!("The {name} opcodes: their numbers and their layout.")),
        at(""),
        at(&format!("Generated by the `protocol` tool from {source}.")),
        at("**Do not edit.** Change the declaration and generate again;"),
        at("a test fails if this file is out of date."),
    ]
}

fn python_bool(v: bool) -> &'static str {
    if v {
        "True"
    } else {
        "False"
    }
}

fn constant(o: &Opcode, radix: &str) -> String {
    format!("{:<16} = {radix}{:02X}", o.name, o.code)
}

pub fn python(d: &Declaration, source: &str) -> String {
    let head = header(&d.name, source, "");
    let mut out = vec![format!("\"\"\"{}", head[0]), String::new()];
    out.extend(head[2..].iter().cloned());
    out.push("\"\"\"".into());
    out.push(String::new());

    for o in &d.opcodes {
        out.push(constant(o, "0x"));
    }
    out.push(String::new());
    out.push(String::new());

    out.push("# How many bytes each fixed-size instruction takes, opcode included.".into());
    out.push("# Derived from the declared arguments; never written down.".into());
    out.push("OPCODE_SIZE = {".into());
    for o in d.opcodes.iter().filter(|o| o.repeated.is_none()) {
        out.push(format!("    {}: {},", o.name, o.fixed_size()));
    }
    out.push("}".into());
    out.push(String::new());

    out.push("# The variable-size ones, as (base, where the count is, how big one".into());
    out.push("# entry is): the size is base + count * entry.".into());
    out.push("VARIABLE_SIZE = {".into());
    for o in d.opcodes.iter().filter(|o| o.repeated.is_some()) {
        out.push(format!(
            "    {}: ({}, {}, {}),",
            o.name,
            o.fixed_size(),
            o.count_offset(),
            o.entry_size()
        ));
    }
    out.push("}".into());
    out.push(String::new());

    out.push("# Each one's arguments, in order, as (name, bytes, signed).".into());
    out.push("LAYOUT = {".into());
    for o in &d.opcodes {
        let args: Vec<String> = o
            .args
            .iter()
            .map(|a| {
                format!(
                    "(\"{}\", {}, {})",
                    a.name,
                    a.kind.size(),
                    python_bool(a.signed)
                )
            })
            .collect();
        // A one-element tuple needs its trailing comma or it is not a tuple.
        let tail = if o.args.len() == 1 { "," } else { "" };
        out.push(format!("    {}: ({}{tail}),", o.name, args.join(", ")));
    }
    out.push("}".into());
    out.push(String::new());
    out.push(String::new());

    out.extend(
        [
            "def opcode_size(code, i=0):",
            "    \"\"\"How many bytes the opcode starting at `code[i]` takes.\"\"\"",
            "    op = code[i]",
            "    variable = VARIABLE_SIZE.get(op)",
            "    if variable is not None:",
            "        base, count, entry = variable",
            "        return base + entry * code[i + count]",
            "    size = OPCODE_SIZE.get(op)",
            "    if size is None:",
            "        raise ValueError(f\"unknown opcode: 0x{op:02X}\")",
            "    return size",
            "",
        ]
        .iter()
        .map(|s| s.to_string()),
    );
    out.join("\n")
}

/// The constants as a Rust module: one `pub const` per opcode, and each
/// fixed-size one's size, for a side written in Rust. It is the Python
/// module's content without its layout table, which nothing in Rust reads.
pub fn rust(d: &Declaration, source: &str) -> String {
    let mut out = header(&d.name, source, "//");
    out.push(String::new());
    for o in &d.opcodes {
        out.push(format!("pub const {}: u8 = 0x{:02X};", o.name, o.code));
    }
    out.push(String::new());
    out.push("/// How many bytes each fixed-size instruction takes, opcode included.".into());
    out.push("/// Derived from the declared arguments; never written down.".into());
    out.push("pub const OPCODE_SIZE: &[(u8, usize)] = &[".into());
    for o in d.opcodes.iter().filter(|o| o.repeated.is_none()) {
        out.push(format!("    ({}, {}),", o.name, o.fixed_size()));
    }
    out.push("];".into());
    out.push(String::new());
    out.push("/// The variable-size ones, as (opcode, base, where the count is, how big".into());
    out.push("/// one entry is): the size is base + count * entry.".into());
    out.push("pub const VARIABLE_SIZE: &[(u8, usize, usize, usize)] = &[".into());
    for o in d.opcodes.iter().filter(|o| o.repeated.is_some()) {
        out.push(format!(
            "    ({}, {}, {}, {}),",
            o.name,
            o.fixed_size(),
            o.count_offset(),
            o.entry_size()
        ));
    }
    out.push("];".into());
    out.push(String::new());
    out.join("\n")
}

/// The equates, and with `jump_table` a macro that lays down one `.addr` per
/// opcode in the order of their numbers, for an indirect `jmp (table, x)`.
///
/// The handler of `OP_SWITCH` is `op_switch`: the opcode's name in lower case.
/// That is a rule and not a field on purpose. A field would be a second name
/// to keep in step with the first, and the declaration would start saying
/// something about the reader's code; the rule says only how to spell one
/// name the declaration already has.
///
/// A macro and not the table itself because the equates are included where
/// the reader wants its constants, and the table has to land where the reader
/// puts its code: which segment, next to which dispatch, is the reader's
/// business.
pub fn asm(d: &Declaration, source: &str, jump_table: bool) -> Result<String, String> {
    let mut out = header(&d.name, source, ";");
    out.push(String::new());
    for o in &d.opcodes {
        out.push(constant(o, "$"));
    }
    out.push(String::new());
    if jump_table {
        let ordered = d.in_code_order()?;
        let prefix = d.name.to_uppercase();
        out.push("; How many opcodes there are: every number below this one is declared,".into());
        out.push("; so an opcode at or above it is not one, and must not index the table.".into());
        out.push(format!("{prefix}_OPCODE_COUNT = ${:02X}", ordered.len()));
        out.push(String::new());
        out.push("; One `.addr` per opcode, in the order of their numbers, to expand where a".into());
        out.push("; `jmp (table, x)` reads it with X = opcode * 2. Each opcode's handler is".into());
        out.push("; named after it, in lower case, and a missing one does not assemble.".into());
        out.push(format!(".macro {prefix}_HANDLERS"));
        for o in &ordered {
            out.push(format!(
                "    .addr {:<20} ; ${:02X}",
                o.name.to_lowercase(),
                o.code
            ));
        }
        out.push(".endmacro".into());
        out.push(String::new());
    }
    Ok(out.join("\n"))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::declaration::{Arg, Declaration, Opcode, Repeated, Type};

    fn arg(name: &str, kind: Type, count: Option<&str>, signed: bool) -> Arg {
        Arg {
            name: name.into(),
            kind,
            count: count.map(|s| s.into()),
            signed,
        }
    }

    fn sample() -> Declaration {
        Declaration {
            name: "test".into(),
            opcodes: vec![
                Opcode {
                    name: "OP_NONE".into(),
                    code: 0x00,
                    args: vec![],
                    repeated: None,
                },
                Opcode {
                    name: "OP_ONE".into(),
                    code: 0x01,
                    args: vec![arg("x", Type::Word, None, true)],
                    repeated: None,
                },
                Opcode {
                    name: "OP_MANY".into(),
                    code: 0x02,
                    args: vec![arg("n", Type::Byte, Some("items"), false)],
                    repeated: Some(Repeated {
                        name: "items".into(),
                        args: vec![arg("y", Type::Word, None, false)],
                    }),
                },
            ],
        }
    }

    /// A one-element Python tuple without its trailing comma is not a tuple,
    /// it is the element: `LAYOUT[op]` would come back as a string.
    #[test]
    fn a_single_argument_keeps_its_trailing_comma() {
        let out = python(&sample(), "test.toml");
        assert!(out.contains(r#"OP_ONE: (("x", 2, True),),"#), "{out}");
        assert!(out.contains("OP_NONE: (),"), "{out}");
    }

    #[test]
    fn the_sizes_are_derived_and_the_variable_ones_are_apart() {
        let out = python(&sample(), "test.toml");
        assert!(out.contains("    OP_ONE: 3,"), "{out}");
        assert!(out.contains("    OP_MANY: (2, 1, 2),"), "{out}");
        // A variable-sized opcode has no entry among the fixed ones.
        let fixed = out.split("OPCODE_SIZE = {").nth(1).unwrap();
        let fixed = fixed.split('}').next().unwrap();
        assert!(!fixed.contains("OP_MANY"), "{fixed}");
    }

    #[test]
    fn the_generated_python_is_valid_and_says_what_it_should() {
        let out = python(&sample(), "test.toml");
        assert!(out.starts_with("\"\"\"The test opcodes"), "{out}");
        assert!(out.ends_with('\n'), "no trailing newline");
    }

    /// An invisible trailing space would show up as a diff on every tree that
    /// regenerates with a different tool.
    #[test]
    fn no_generated_line_ends_in_whitespace() {
        for text in [
            python(&sample(), "t.toml"),
            asm(&sample(), "t.toml", false).unwrap(),
            asm(&sample(), "t.toml", true).unwrap(),
            rust(&sample(), "t.toml"),
        ] {
            for (n, line) in text.lines().enumerate() {
                assert_eq!(line, line.trim_end(), "line {} of {text}", n + 1);
            }
        }
    }

    #[test]
    fn the_rust_output_is_constants_and_sizes() {
        let out = rust(&sample(), "test.toml");
        assert!(out.starts_with("// The test opcodes"), "{out}");
        assert!(out.contains("pub const OP_ONE: u8 = 0x01;"), "{out}");
        assert!(out.contains("    (OP_ONE, 3),"), "{out}");
        assert!(out.contains("    (OP_MANY, 2, 1, 2),"), "{out}");
        assert!(out.ends_with('\n'), "no trailing newline");
    }

    #[test]
    fn the_assembler_output_is_equates_and_nothing_else() {
        let out = asm(&sample(), "test.toml", false).unwrap();
        assert!(out.contains("OP_MANY          = $02"), "{out}");
        assert!(!out.contains("OPCODE_SIZE"), "{out}");
        assert!(!out.contains(".macro"), "{out}");
        assert!(!out.contains("COUNT"), "{out}");
    }

    /// Entry k of the table is the handler of opcode k, whatever order the
    /// declaration lists them in: that is the whole contract of the table.
    #[test]
    fn the_jump_table_follows_the_numbers_and_lowercases_the_names() {
        let mut d = sample();
        d.opcodes.reverse();
        let out = asm(&d, "test.toml", true).unwrap();
        let addrs: Vec<&str> = out
            .lines()
            .filter_map(|l| l.trim_start().strip_prefix(".addr "))
            .map(|l| l.split_whitespace().next().unwrap())
            .collect();
        assert_eq!(addrs, ["op_none", "op_one", "op_many"], "{out}");
        assert!(out.contains("TEST_OPCODE_COUNT = $03"), "{out}");
        assert!(out.contains(".macro TEST_HANDLERS"), "{out}");
        assert!(out.trim_end().ends_with(".endmacro"), "{out}");
    }

    #[test]
    fn a_jump_table_with_a_gap_is_refused() {
        let mut d = sample();
        d.opcodes[2].code = 0x05;
        let e = asm(&d, "test.toml", true).unwrap_err();
        assert!(e.contains("0x02, 0x03, 0x04"), "{e}");
        // Without the table, the same declaration is fine.
        assert!(asm(&d, "test.toml", false).is_ok());
    }
}
